import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.CvydjLy7.js";const g=JSON.parse('{"title":"11.1 可执行 jar 里装了什么","description":"","frontmatter":{"title":"11.1 可执行 jar 里装了什么"},"headers":[{"level":3,"title":"目录骨架","slug":"目录骨架","link":"#目录骨架","children":[]},{"level":3,"title":"MANIFEST.MF 里的六个字段","slug":"manifest-mf-里的六个字段","link":"#manifest-mf-里的六个字段","children":[]},{"level":3,"title":"4.x 换了 loader 的包名","slug":"_4-x-换了-loader-的包名","link":"#_4-x-换了-loader-的包名","children":[]}],"relativePath":"ch11/01.md","filePath":"ch11/01.md","lastUpdated":1789497795000}'),p={name:"ch11/01.md"};function o(r,a,i,c,l,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="_11-1-可执行-jar-里装了什么" tabindex="-1">11.1 可执行 jar 里装了什么 <a class="header-anchor" href="#_11-1-可执行-jar-里装了什么" aria-label="Permalink to &quot;11.1 可执行 jar 里装了什么&quot;">​</a></h1><p><code>mvn package</code> 之后，<code>target/</code> 下会出现两个文件：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>target/activity-server-1.0.0.jar           64635306 字节</span></span>
<span class="line"><span>target/activity-server-1.0.0.jar.original     51 KB</span></span></code></pre></div><p>构建日志里写明了这两个文件的关系：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[INFO] --- spring-boot:4.1.1:repackage (repackage) @ activity-server ---</span></span>
<span class="line"><span>[INFO] Replacing main artifact .../activity-server-1.0.0.jar with repackaged archive,</span></span>
<span class="line"><span>       adding nested dependencies in BOOT-INF/.</span></span>
<span class="line"><span>[INFO] The original artifact has been renamed to .../activity-server-1.0.0.jar.original</span></span></code></pre></div><p><code>maven-jar-plugin</code> 先打出普通的 jar（只有编译产物，51KB），随后 <code>spring-boot-maven-plugin</code> 的 <code>repackage</code> 目标把它重新打包成可执行 jar，原始产物改名为 <code>.jar.original</code> 留在旁边。这个 <code>.original</code> 文件没什么用，但它解释了“为什么我的 jar 突然从 51KB 变成 62MB”——依赖被塞进来了。</p><h3 id="目录骨架" tabindex="-1">目录骨架 <a class="header-anchor" href="#目录骨架" aria-label="Permalink to &quot;目录骨架&quot;">​</a></h3><p>解开可执行 jar，顶层只有四个目录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BOOT-INF/classes/     应用自己的类和活动（application.yml、data.sql 都在这）</span></span>
<span class="line"><span>BOOT-INF/lib/         所有依赖 jar，一个不落地以嵌套形式放在这</span></span>
<span class="line"><span>META-INF/             MANIFEST.MF、maven 元数据、services 声明</span></span>
<span class="line"><span>org/springframework/boot/loader/   启动器代码</span></span></code></pre></div><p>体积分布很能说明问题：</p><table tabindex="0"><thead><tr><th>目录</th><th>大小</th><th>占比</th></tr></thead><tbody><tr><td><code>BOOT-INF/lib</code></td><td>62 MB</td><td>99.6%</td></tr><tr><td><code>BOOT-INF/classes</code></td><td>272 KB</td><td>0.4%</td></tr><tr><td><code>org/springframework/boot/loader</code></td><td>604 KB</td><td>1%</td></tr><tr><td><code>META-INF</code></td><td>20 KB</td><td>—</td></tr></tbody></table><p>单个依赖占前几名的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hibernate-core-7.4.5.Final.jar        15 MB</span></span>
<span class="line"><span>byte-buddy-1.18.11.jar               4.4 MB</span></span>
<span class="line"><span>tomcat-embed-core-11.0.24.jar        3.5 MB</span></span>
<span class="line"><span>h2-2.4.240.jar                       2.6 MB</span></span>
<span class="line"><span>spring-web-7.0.9.jar                 2.1 MB</span></span>
<span class="line"><span>aspectjweaver-1.9.25.1.jar           2.1 MB</span></span></code></pre></div><p>记住这个比例：<strong>你自己的代码不到千分之五，其余全是依赖</strong>。后面讲分层和镜像构建缓存时，所有优化都建立在这个事实上。</p><h3 id="manifest-mf-里的六个字段" tabindex="-1">MANIFEST.MF 里的六个字段 <a class="header-anchor" href="#manifest-mf-里的六个字段" aria-label="Permalink to &quot;MANIFEST.MF 里的六个字段&quot;">​</a></h3><p><code>META-INF/MANIFEST.MF</code> 是理解可执行 jar 的钥匙：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Main-Class: org.springframework.boot.loader.launch.JarLauncher</span></span>
<span class="line"><span>Start-Class: com.example.activity.ActivityServerApplication</span></span>
<span class="line"><span>Spring-Boot-Version: 4.1.1</span></span>
<span class="line"><span>Spring-Boot-Classes: BOOT-INF/classes/</span></span>
<span class="line"><span>Spring-Boot-Lib: BOOT-INF/lib/</span></span>
<span class="line"><span>Spring-Boot-Classpath-Index: BOOT-INF/classpath.idx</span></span>
<span class="line"><span>Spring-Boot-Layers-Index: BOOT-INF/layers.idx</span></span></code></pre></div><p>三件事值得说：</p><p><strong><code>Main-Class</code> 指向框架的类，不是你的主类。</strong> 这是最容易让人困惑的一点。<code>java -jar</code> 只会调用 <code>Main-Class</code> 的 <code>main</code> 方法，而它指向 <code>JarLauncher</code>——框架的启动器。你的主类写在 <code>Start-Class</code> 里，由 <code>JarLauncher</code> 读出来再反射调用。</p><p>为什么绕这一圈？因为 <strong>JDK 不认识嵌套 jar</strong>。<code>BOOT-INF/lib/hibernate-core-7.4.5.Final.jar</code> 是 jar 里的 jar，标准类加载器打不开它。<code>JarLauncher</code> 做的工作就是自建一套类加载机制，把这些嵌套 jar 展开成可加载的 classpath，然后再启动你的应用。</p><p><strong><code>Spring-Boot-Classes</code> 与 <code>Spring-Boot-Lib</code> 声明了这两类内容的相对路径。</strong> <code>JarLauncher</code> 靠这两个字段定位，所以你手动改目录结构会直接启动失败。</p><p><strong><code>Spring-Boot-Layers-Index</code> 有一定就有。</strong> 只要用 <code>spring-boot-maven-plugin</code> 打包，<code>BOOT-INF/layers.idx</code> 就会生成，不需要额外配置——这一点和很多文章说的“要手动开分层”不一样。</p><h3 id="_4-x-换了-loader-的包名" tabindex="-1">4.x 换了 loader 的包名 <a class="header-anchor" href="#_4-x-换了-loader-的包名" aria-label="Permalink to &quot;4.x 换了 loader 的包名&quot;">​</a></h3><p><code>org/springframework/boot/loader/</code> 下的子包分布：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>31  net/      网络协议相关（jar:、nested: 的 URL 处理）</span></span>
<span class="line"><span>28  zip/      ZIP 解析</span></span>
<span class="line"><span>19  launch/   启动器，JarLauncher、WarLauncher、PropertiesLauncher 在这里</span></span>
<span class="line"><span>15  jar/      嵌套 jar 的文件系统抽象</span></span>
<span class="line"><span> 9  nio/</span></span>
<span class="line"><span> 4  log/</span></span>
<span class="line"><span> 3  ref/</span></span>
<span class="line"><span> 3  jarmode/  命令行模式，就是后面 jarmode=tools 的入口</span></span></code></pre></div><p><code>launch</code> 这个包名是 Boot 3.2 之后启用的，2.x 与 3.0/3.1 里启动器直接在 <code>loader</code> 包下（<code>org.springframework.boot.loader.JarLauncher</code>）。如果你维护的老项目里写过自定义启动器、或者有代码 <code>import org.springframework.boot.loader.JarLauncher</code>，升级时会遇到“找不到符号”，原因就在这里。</p><hr>`,27)])])}const b=e(p,[["render",o]]);export{g as __pageData,b as default};
